CREATE TABLE sale_posts (id BIGINT AUTO_INCREMENT PRIMARY KEY, seller_id BIGINT NOT NULL, title VARCHAR(100) NOT NULL, content TEXT NOT NULL, price DECIMAL(15,2) NOT NULL, status VARCHAR(20) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, CONSTRAINT fk_sale_seller FOREIGN KEY (seller_id) REFERENCES users(id));
CREATE TABLE sale_post_images (id BIGINT AUTO_INCREMENT PRIMARY KEY, sale_post_id BIGINT NOT NULL, object_key VARCHAR(255) NOT NULL, sort_order INT NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, CONSTRAINT fk_sale_image FOREIGN KEY (sale_post_id) REFERENCES sale_posts(id));
